namespace Api.Web.FinanceIA.Models.Financia;

/// <summary>
/// EF Core entity that maps to [dbo].[AnalysisEdits] (DDL 001, TenantId retyped by DDL 081): one row per
/// figure of an extracted balance an analyst corrected by hand (POST /api/analyses/{resultId}/balance-
/// corrections). APPEND-ONLY — rows are inserted in the same transaction as the corrected BalanceJson and
/// the re-score, and are never updated or deleted.
/// </summary>
public sealed class AnalysisEdit
{
    /// <summary>Primary key. IDENTITY — generated by the database.</summary>
    public long AnalysisEditId { get; set; }

    /// <summary>The analysis (Analyses.AnalysisId) whose result was corrected.</summary>
    public Guid AnalysisId { get; set; }

    /// <summary>Tenant that owns the row. Firebase tenant slug (DDL 081), not a GUID.</summary>
    public string TenantId { get; set; } = string.Empty;

    /// <summary>Users.UserId of the analyst.</summary>
    public Guid EditedBy { get; set; }

    /// <summary>The BalanceJson path, e.g. <c>current_assets</c> or <c>current_assets_items[2].amount</c>.</summary>
    public string FieldPath { get; set; } = string.Empty;

    /// <summary>The value immediately before this correction, as an invariant-culture number, or null.</summary>
    public string? OldValue { get; set; }

    /// <summary>The corrected value, as an invariant-culture number, or null (the figure cleared).</summary>
    public string? NewValue { get; set; }

    /// <summary>The analyst's reason, shared by every row of one correction. Free text: never logged.</summary>
    public string? EditReason { get; set; }

    /// <summary>UTC. Set by the application to the re-score's own instant.</summary>
    public DateTime EditedAt { get; set; }
}
